package com.auth.service

import javax.xml.parsers.{DocumentBuilderFactory, SAXParserFactory}
import javax.xml.transform.sax.SAXSource
import javax.xml.XMLConstants
import org.xml.sax.InputSource
import java.io.StringReader
import java.util.concurrent.atomic.{AtomicInteger, AtomicLong}
import scala.util.{Try, Success, Failure}
import scala.xml.{XML, Elem}

sealed trait CircuitState
case object Closed extends CircuitState
case object Open extends CircuitState
case object HalfOpen extends CircuitState

case class CircuitBreakerConfig(
  failureThreshold: Int = 5,
  resetTimeoutMs: Long = 30000,
  halfOpenMaxCalls: Int = 1
)

class CircuitBreaker(config: CircuitBreakerConfig) {
  private val state = new java.util.concurrent.atomic.AtomicReference[CircuitState](Closed)
  private val failureCount = new AtomicInteger(0)
  private val lastFailureTime = new AtomicLong(0)
  private val halfOpenCalls = new AtomicInteger(0)

  def execute[T](operation: => T): Try[T] = {
    state.get() match {
      case Open =>
        if (System.currentTimeMillis() - lastFailureTime.get() > config.resetTimeoutMs) {
          state.compareAndSet(Open, HalfOpen)
          halfOpenCalls.set(0)
          attemptCall(operation)
        } else {
          Failure(new RuntimeException("Circuit breaker is open"))
        }
      case HalfOpen =>
        if (halfOpenCalls.incrementAndGet() <= config.halfOpenMaxCalls) {
          attemptCall(operation)
        } else {
          Failure(new RuntimeException("Circuit breaker half-open limit reached"))
        }
      case Closed =>
        attemptCall(operation)
    }
  }

  private def attemptCall[T](operation: => T): Try[T] = {
    Try(operation) match {
      case success @ Success(_) =>
        onSuccess()
        success
      case failure @ Failure(_) =>
        onFailure()
        failure
    }
  }

  private def onSuccess(): Unit = {
    failureCount.set(0)
    state.set(Closed)
  }

  private def onFailure(): Unit = {
    val count = failureCount.incrementAndGet()
    lastFailureTime.set(System.currentTimeMillis())
    if (count >= config.failureThreshold) {
      state.set(Open)
    }
  }
}

trait XmlParserProvider {
  def createSecureParser(): DocumentBuilderFactory
}

object DefaultXmlParserProvider extends XmlParserProvider {
  override def createSecureParser(): DocumentBuilderFactory = {
    val factory = DocumentBuilderFactory.newInstance()
    factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true)
    factory.setFeature("http://xml.org/sax/features/external-general-entities", false)
    factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false)
    factory.setXIncludeAware(false)
    factory.setExpandEntityReferences(false)
    factory
  }
}

class SAMLResponseParser(parserProvider: XmlParserProvider) {

  private def parseXmlDocument(xmlContent: String): org.w3c.dom.Document = {
    val factory = parserProvider.createSecureParser()
    val builder = factory.newDocumentBuilder()
    val inputSource = new InputSource(new StringReader(xmlContent))
    builder.parse(inputSource)
  }

  def extractAssertion(xmlContent: String): Try[String] = {
    Try {
      val doc = parseXmlDocument(xmlContent)
      val assertions = doc.getElementsByTagNameNS("urn:oasis:names:tc:SAML:2.0:assertion", "Assertion")
      if (assertions.getLength > 0) {
        assertions.item(0).getTextContent
      } else {
        throw new RuntimeException("No assertion found in SAML response")
      }
    }
  }
}

class AuthenticationService(
  circuitBreaker: CircuitBreaker,
  samlParser: SAMLResponseParser
) {

  private val metadataCache = new java.util.concurrent.ConcurrentHashMap[String, String]()

  def authenticate(samlResponse: String): Try[AuthResult] = {
    circuitBreaker.execute {
      val assertion = samlParser.extractAssertion(samlResponse)
      assertion match {
        case Success(content) => validateAndExtract(content)
        case Failure(e) => throw e
      }
    }
  }

  def refreshMetadata(entityId: String, metadataXml: String): Try[Unit] = {
    circuitBreaker.execute {
      val parsed = parseMetadataFallback(metadataXml)
      metadataCache.put(entityId, parsed)
      ()
    }
  }

  private def parseMetadataFallback(metadataXml: String): String = {
    val saxFactory = SAXParserFactory.newInstance()
    saxFactory.setNamespaceAware(true)
    // Enable secure processing to bound internal entity expansion (billion-laughs DoS protection).
    saxFactory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true)
    saxFactory.setFeature("http://xml.org/sax/features/external-general-entities", false)
    saxFactory.setFeature("http://xml.org/sax/features/external-parameter-entities", false)
    val saxParser = saxFactory.newSAXParser()
    val source = new SAXSource(saxParser.getXMLReader, new InputSource(new StringReader(metadataXml)))
    val elem = XML.loadXML(source, saxParser)
    (elem \\ "EntityDescriptor").headOption.map(_.toString).getOrElse(
      throw new RuntimeException("Invalid metadata format")
    )
  }

  private def validateAndExtract(assertionContent: String): AuthResult = {
    AuthResult(
      userId = extractAttribute(assertionContent, "uid"),
      email = extractAttribute(assertionContent, "email"),
      roles = extractRoles(assertionContent)
    )
  }

  private def extractAttribute(content: String, name: String): String = {
    val pattern = s"(?s).*$name[^>]*>([^<]+)<.*".r
    content match {
      case pattern(value) => value.trim
      case _ => ""
    }
  }

  private def extractRoles(content: String): List[String] = {
    val pattern = "role[^>]*>([^<]+)<".r
    pattern.findAllMatchIn(content).map(_.group(1).trim).toList
  }
}

case class AuthResult(userId: String, email: String, roles: List[String])

object AuthenticationService {
  def create(config: CircuitBreakerConfig = CircuitBreakerConfig()): AuthenticationService = {
    val cb = new CircuitBreaker(config)
    val parser = new SAMLResponseParser(DefaultXmlParserProvider)
    new AuthenticationService(cb, parser)
  }
}
